# CLI binary — clap + miette diagnostics.
cli = ["dep:clap", "miette"]

# Miette Diagnostic derive on MonoklError — forwarded to stubhub-errors for full chain rendering.
miette = ["dep:miette", "stubhub-errors/miette"]


[dependencies]
stubhub-errors = { path = "../stubhub-errors", version = "0.1", registry = "sh-cargo", default-features = false }

blake3        = { workspace = true }
camino        = { workspace = true }
