1531	    let mut cache = if let Some(ref existing) = state.cache_file {
1532	        existing.clone()
1533	    } else {
1534	        load_cache(root, config_hash)?
1535	    };
1536	    for (path, entry) in state.write_queue.drain(..) {
1537	        cache.entries.insert(path, entry);
1538	    }
1539	    cache.version = CACHE_VERSION;
1540	    cache.config_hash = config_hash.to_string();
1541	    let json_str = {
1542	        let serialized = serde_json::to_string_pretty(&cache)?;
1543	        if serialized.len() > MAX_CACHE_BYTES {
1544	            evict_lru(&mut cache, MAX_CACHE_BYTES)?
1545	        } else {
1546	            serialized
1547	        }
1548	    };
1549	    let cache_dir = root.join(".monokl");
1550	    std::fs::create_dir_all(&cache_dir).map_err(|e| FileIoError::create_dir(&cache_dir, e))?;
1551	    let cache_path = root.join(".monokl/cache.json");
1552	    let temp_path = root.join(format!(".monokl/cache.json.{}.tmp", std::process::id()));
1553	    std::fs::write(&temp_path, &json_str).map_err(|e| FileIoError::write(&temp_path, e))?;
1554	    std::fs::rename(&temp_path, &cache_path).map_err(|e| FileIoError::write(&cache_path, e))?;
1555	    state.cache_file = Some(cache);
1556	    Ok(())
