1755	    };
1756	    let persisted = persist::PersistedFileAnalysis {
1757	        content_hash: content_hash.clone(),
1758	        mtime_ns, size_bytes,
1759	        symbols: symbols.clone(),
1760	        dependencies: dependencies.clone(),
1761	        exports: exports.clone(),
1762	        ts_data: Some(ts_data.clone()),
1763	        blocks: blocks.clone(),
1764	        had_parse_errors,
1765	        last_accessed_ns: 0,
1766	    };
1767	    persist::queue_write(path, persisted);
1768	    FileAnalysis {
1769	        source_path: path.to_owned(),
1770	        content_hash,
