2046	use std::sync::Arc;
2047	use camino::{Utf8Path, Utf8PathBuf};
2048	use rayon::prelude::*;
2049	use rustc_hash::FxHashMap;
2050	use crate::analysis::file_analysis::FileAnalysis;
2051	use crate::analysis::lang::LanguageAnalyzer;
2052	use crate::enrich::WorkspaceEnricher;
2053	use crate::error::Result;
2054	use super::file_idx::FileIdx;
2055	use super::import_graph::ImportGraph;
2056	use super::symbol_index::SymbolIndex;
