2135	        use crate::analysis::TsAnalyzer;
2136	        use crate::enrich::import_graph::ImportGraphEnricher;
2137	        use crate::enrich::symbol_index::SymbolIndexEnricher;
2138	        let analyzer = TsAnalyzer::from_workspace_opts(opts)?;
2139	        let config_hash = TsAnalyzer::config_hash_for(opts);
2140	        let enrichers: Vec<Box<dyn WorkspaceEnricher>> = vec![
2141	            Box::new(ImportGraphEnricher::new()),
