2148	        let Some(idx) = self.path_to_idx(file) else { return Vec::new(); };
2149	        self.import_graph.dependents(idx).iter()
2150	            .filter_map(|&dep_idx| self.idx_to_path(dep_idx)).collect()
2151	    }
