5729	fn is_exported_item<T>(item: &T) -> bool where T: HasAttrs + HasVisibility {
5730	    item.visibility().is_some() || has_napi_attr(item)
5731	}
5732	
5733	fn has_napi_attr<T>(item: &T) -> bool where T: HasAttrs {
5734	    item.attrs().any(|attr| {
5735	        let text = attr.syntax().text().to_string();
5736	        let text = text.trim();
5737	        text.strip_prefix("#[")
5738	            .and_then(|rest| rest.split(['(', ']', ' ']).next())
5739	            .is_some_and(|name| name == "napi")
5740	    })
5741	}
5742	```
5743	
5744	`#[napi]` / `#[napi(object)]` annotated items are exported even without explicit visibility — this matches the napi-rs convention where the macro produces extern-visible bindings regardless of Rust `pub`.
