5985	### `pipeline/inspecting.rs`
5986	
5987	Owns `extract` and `patterns`. Extract flow:
5988	
5989	```rust
5990	pub(super) fn extract(req: &ExtractRequest) -> Result<ExtractResult> {
5991	    let root = session::absolute_workspace_root(req.file.parent())?;
5992	    let session = session::for_workspace(&WorkspaceOptions::new(root))?;
5993	    let Some(analyzer) = session.registry().analyzer_for(&req.file) else {
5994	        let mut diagnostics = Vec::new();
5995	        add_missing_analyzer_diagnostic("extract", &req.file, &mut diagnostics);
5996	        return Ok(ExtractResult { blocks: Vec::new(), diagnostics });
5997	    };
5998	
5999	    let file_for_closure = req.file.clone();
6000	    let full = analyzer.analyze(&req.file, Box::new(move || {
6001	        std::fs::read_to_string(file_for_closure.as_std_path())
6002	            .map_err(|e| MonoklError::Io(FileIoError::read(&file_for_closure, e)))
6003	    }))?;
6004	
6005	    let mut diagnostics = Vec::new();
6006	    if full.had_parse_errors { /* push Degraded diagnostic */ }
6007	
6008	    let blocks = full.blocks.iter()
6009	        .filter(|block| match (req.line_start, req.line_end) {
6010	            (None, None) => true,
6011	            (Some(start), None) => block.line_start <= start && block.line_end >= start,
6012	            (None, Some(end)) => block.line_start <= end,
6013	            (Some(start), Some(end)) => block.line_start <= end && block.line_end >= start,
6014	        })
6015	        .cloned()
6016	        .collect();
6017	
6018	    Ok(ExtractResult { blocks, diagnostics })
6019	}
6020	```
