657	#[derive(Debug, Clone, PartialEq)]
658	pub enum Token {
659	    Plus,
660	    Minus,
661	    RegexPrefix,
662	    QuotedString(String),
663	    Word(String),
664	    Eof,
665	}
666	
667	pub struct Lexer<'a> {
668	    input: &'a str,
669	    pos: usize,
670	}
671	
672	impl<'a> Lexer<'a> {
673	    pub fn new(input: &'a str) -> Self {
674	        Self { input, pos: 0 }
675	    }
676	
677	    fn remaining(&self) -> &str {
678	        &self.input[self.pos..]
679	    }
680	
681	    fn peek(&self) -> Option<char> {
682	        self.remaining().chars().next()
683	    }
684	
685	    fn advance(&mut self) -> Option<char> {
686	        let ch = self.peek()?;
687	        self.pos += ch.len_utf8();
688	        Some(ch)
689	    }
690	
691	    fn skip_whitespace(&mut self) {
692	        while let Some(ch) = self.peek() {
693	            if ch.is_ascii_whitespace() {
694	                self.pos += ch.len_utf8();
695	            } else {
696	                break;
697	            }
698	        }
699	    }
700	
701	    fn read_word(&mut self) -> String {
702	        let mut s = String::new();
703	        loop {
704	            match self.peek() {
705	                None => break,
706	                Some(ch) if ch.is_ascii_whitespace() => break,
707	                Some(ch) => {
708	                    s.push(ch);
709	                    self.pos += ch.len_utf8();
710	                }
711	            }
712	        }
713	        s
714	    }
715	
716	    fn read_quoted(&mut self) -> String {
717	        let mut s = String::new();
718	        loop {
719	            match self.advance() {
720	                None | Some('"') => break,
721	                Some('\\') => {
722	                    match self.peek() {
723	                        Some('"') => {
724	                            self.pos += 1;
725	                            s.push('"');
726	                        }
727	                        _ => s.push('\\'),
728	                    }
729	                }
730	                Some(ch) => s.push(ch),
731	            }
732	        }
733	        s
734	    }
735	
736	    pub fn next_token(&mut self) -> Token {
737	        self.skip_whitespace();
738	        match self.peek() {
739	            None => Token::Eof,
740	            Some('+') => { self.pos += 1; Token::Plus }
741	            Some('-') => { self.pos += 1; Token::Minus }
742	            Some('"') => { self.pos += 1; Token::QuotedString(self.read_quoted()) }
743	            Some(_) => {
744	                if self.remaining().starts_with("regex:") {
745	                    self.pos += "regex:".len();
746	                    Token::RegexPrefix
747	                } else {
748	                    Token::Word(self.read_word())
749	                }
750	            }
751	        }
752	    }
753	}
754	```
755	
756	Rules: `+`/`-` consumed as Token::Plus/Token::Minus only when they begin a term (`read_word` greedily consumes everything except whitespace). `regex:` (case-sensitive) emits RegexPrefix, the next token is the pattern. `\"` is the only recognized escape in quoted strings.
