761	use super::lexer::{Lexer, Token};
762	use crate::error::{MonoklError, Result};
763	
764	#[derive(Debug, Clone, PartialEq, Eq)]
765	pub enum Modifier {
766	    Required,
767	    Excluded,
768	    Optional,
769	}
770	
771	#[derive(Debug, Clone)]
772	pub struct ParsedTerm {
773	    pub modifier: Modifier,
774	    pub pattern: String,
775	    pub is_regex: bool,
776	}
777	
778	pub fn parse(input: &str) -> Result<Vec<ParsedTerm>> {
779	    const LIMIT: usize = 64;
780	    if input.trim().is_empty() {
781	        return Ok(Vec::new());
782	    }
783	    let mut lexer = Lexer::new(input);
784	    let mut terms: Vec<ParsedTerm> = Vec::new();
785	    loop {
786	        let tok = lexer.next_token();
787	        match tok {
788	            Token::Eof => break,
789	            Token::Plus => {
790	                let content = lexer.next_token();
791	                if let Some(term) = content_to_term(content, Modifier::Required) {
792	                    terms.push(term);
793	                }
794	            }
795	            Token::Minus => {
796	                let content = lexer.next_token();
797	                if let Some(term) = content_to_term(content, Modifier::Excluded) {
798	                    terms.push(term);
799	                }
800	            }
801	            Token::RegexPrefix => {
802	                let pattern_tok = lexer.next_token();
803	                match pattern_tok {
804	                    Token::Word(raw) | Token::QuotedString(raw) => {
805	                        terms.push(ParsedTerm {
806	                            modifier: Modifier::Optional,
807	                            pattern: raw,
808	                            is_regex: true,
809	                        });
810	                    }
811	                    _ => {}
812	                }
813	            }
814	            Token::Word(w) => {
815	                terms.push(ParsedTerm {
816	                    modifier: Modifier::Optional,
817	                    pattern: regex::escape(&w),
818	                    is_regex: false,
819	                });
820	            }
821	            Token::QuotedString(s) => {
822	                terms.push(ParsedTerm {
823	                    modifier: Modifier::Optional,
824	                    pattern: regex::escape(&s),
825	                    is_regex: false,
826	                });
827	            }
828	        }
829	    }
830	    if terms.len() > LIMIT {
831	        return Err(MonoklError::TooManyTerms {
832	            count: terms.len(),
833	            limit: LIMIT,
834	        });
835	    }
836	    Ok(terms)
837	}
838	
839	fn content_to_term(tok: Token, modifier: Modifier) -> Option<ParsedTerm> {
840	    match tok {
841	        Token::Word(w) => Some(ParsedTerm {
842	            modifier,
843	            pattern: regex::escape(&w),
844	            is_regex: false,
845	        }),
846	        Token::QuotedString(s) => Some(ParsedTerm {
847	            modifier,
848	            pattern: regex::escape(&s),
849	            is_regex: false,
850	        }),
851	        Token::RegexPrefix => None, // `+regex:foo` documented as silently losing modifier
852	        _ => None,
853	    }
854	}
855	```
