874	        let required: Vec<usize> = terms.iter().enumerate()
875	            .filter(|(_, t)| t.modifier == Modifier::Required)
876	            .map(|(i, _)| i).collect();
877	        let excluded: Vec<usize> = terms.iter().enumerate()
878	            .filter(|(_, t)| t.modifier == Modifier::Excluded)
879	            .map(|(i, _)| i).collect();
880	        let scored: Vec<usize> = terms.iter().enumerate()
881	            .filter(|(_, t)| t.modifier == Modifier::Optional)
882	            .map(|(i, _)| i).collect();
883	        Self { terms, required, excluded, scored }
884	    }
885	
886	    pub fn is_empty(&self) -> bool { self.terms.is_empty() }
887	
888	    pub fn search_patterns(&self) -> Vec<&str> {
889	        self.required.iter().chain(self.scored.iter())
890	            .map(|&i| self.terms[i].pattern.as_str())
891	            .collect()
892	    }
893	}
